INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(123481, 'ruRU', '', 'Узрите эту разношёрстную толпу, в которую мятежники вложили свою веру.', 24330),
(123482, 'ruRU', '', 'Калдорай? Вы бесчестите славное прошлое, прячась по деревьям и облекая себя лживым благочестием. Вы стали так же дики, как и тролли, что рыщут по вашим лесам.', 24330),
(123483, 'ruRU', '', 'Кель''дорай? Вы крестьяне, играющие в благородство, слишком охотно смешивающиеся с низшими расами, разбавляющими вашу кровь. Вы недостойны имени высших эльфов.', 24330),
(123484, 'ruRU', '', 'Синдорай? Из всех эльфов я думала, что именно вы поймёте выбор, что я сделала, чтобы спасти свой народ. Но вместо этого вы встаёте в союз с изгоями и монстрами.', 24330),
(123485, 'ruRU', '', 'Каждый из вас опозорил своё гордое происхождение. Каждый из вас забыл древнюю силу, что является нашим правом по рождению.', 24330),
(123486, 'ruRU', '', 'Но Сурамар помнит! Мы — Ночнорождённые, последние из истинных эльфов. Все остальные — лишь пустые отголоски нашего величия.', 24330),
(123487, 'ruRU', '', 'Пусть этот провалившийся мятеж станет уроком любому, кто встанет против шал''дорай!', 24330),
(123499, 'ruRU', '', 'Лазуэль и я были друзьями с детства. Мы делили друг с другом лучшие моменты наших жизней.', 24330),
(123504, 'ruRU', '', 'Чародейка Талисра. Я помню, на чьей стороне стоял твой орден в Войне древних. Откуда нам знать, что ты не предашь нас и не станешь следующей Элизандой... следующей Азшарой?', 24330),
(123505, 'ruRU', '', 'Калдорай будут сражаться за то, чтобы увидеть Легион побеждённым, а Ночной Колодец уничтоженным. Что до остального... посмотрим, куда приведёт нас мудрость Элуны.', 24330),
(123506, 'ruRU', '', 'А после того, как твоя соперница будет побеждена, почему мы должны верить, что ты не предашь нас за тайную силу Ночного Колодца и не станешь следующей Элизандой... следующей Азшарой?', 24330),
(123507, 'ruRU', '', 'Мы знаем, куда привёл бы нас путь Элизанды, и просим твоей помощи, чтобы положить конец её правлению.', 24330),
(123508, 'ruRU', '', 'Мы не намерены быть рабами Ночного Колодца. Мы стремимся изгнать Легион из Сурамара и положить конец гнёту Элизанды.', 24330),
(123509, 'ruRU', '', '[CUT]If that is your wish, so be it. When this war is won, my people will need allies. It is clear you will not be among them.', 24330),
(123512, 'ruRU', '', 'Я понимаю, что борьба Иссохших отражает нашу собственную, Первый Чародей. Зависимость... предательство...', 24330),
(123513, 'ruRU', '', 'Мы очистим это. Синдорай обрушат праведную ярость на наших врагов.', 24330),
(123514, 'ruRU', '', 'Есть лечение от нашей зависимости, но потребуется время, чтобы применить его ко всему нашему народу. Сначала мы должны свергнуть Элизанду и очистить Сурамар от скверны Легиона.', 24330),
(123520, 'ruRU', '', 'Альтурус, осторожно! Ох, это ты, $n? Ты выглядишь... иначе.', 24330),
(123523, 'ruRU', '', '...Как скажешь.', 24330),
(123524, 'ruRU', '', 'Не незаслуженная реакция. Обычно я была бы обязана убить вас обоих.', 24330),
(123525, 'ruRU', '', 'Нынешние обстоятельства делают нас союзниками.', 24330),
(123529, 'ruRU', '', '|TInterface\\Icons\\inv_misc_monsterhorn_03.blp:20|t %s появляется рядом с Хелией!', 24330),
(123533, 'ruRU', '', 'DELETE ME', 24330),
(123545, 'ruRU', '', 'Мы будем держать периметр!', 24330),
(123547, 'ruRU', '', 'Обязательно научи этого демона уроку.', 24330),
(123550, 'ruRU', '', 'Рад видеть дружелюбное лицо на этом поле боя, $p.$b$bЭто... тяжело... для меня снова ступить по земле Сурамара. Десять тысяч лет прошло с тех пор, как мои ноги последний раз чувствовали траву этой земли.$b$bТогда мы бежали от Пылающего Легиона.$b$bЯ никогда не верил, что вернусь на место своего рождения, чтобы вырвать его из рук тех, кого когда-то считал своим народом.', 24330),
(123551, 'ruRU', '', 'Говори быстро, $r. Я не хочу, чтобы ты задерживался в моём лагере.$b$bТвоя Орда оставила умирать на Расколотом берегу моего хорошего друга. Будь благодарен, что у нас пока общий враг.', 24330),
(123552, 'ruRU', '', 'Когда я позволила тебе взять Слёзы Элуны, я предполагала, что следующая наша встреча произойдёт в финальной битве с Легионом.$b$bЯ не ожидала увидеть тебя в компании зависимых от маны у подножия города моего рождения.$b$bГовори быстро, $r. Я не в настроении для прошений Талисры.', 24330),
(123553, 'ruRU', '', 'Сурамар. Я здесь родился. Ни за десять тысяч лет я не поверил бы, что вернусь с армией, чтобы отнять его у тех самых эльфов, к кому когда-то обращался за защитой.', 24330),
(123555, 'ruRU', '', 'Значит, настало время вести армию на город моего рождения. Пусть Элуна даст нам быстрый конец этому конфликту.', 24330),
(123557, 'ruRU', '', 'Мне нужно поговорить с тобой, защитник. Встреться со мной, как только сможешь.', 24330),
(123558, 'ruRU', '', 'Никогда не думал, что буду делить лагерь с калдорай. Но отчаянные времена требуют отчаянных мер.', 24330),
(123559, 'ruRU', '', 'Для справки, я советовала не доверять никому из Орды в этой кампании. Я потеряла мужа и короля из-за предательства Орды.$b$bЯ не вижу причин доверять тебе ни сейчас, ни когда-либо.', 24330),
(123560, 'ruRU', '', 'Хорошо. У нас недостаточно сил, чтобы долго удерживать это место. Чем скорее мы продвинемся, тем лучше.', 24330),
(123561, 'ruRU', '', 'Мало кто понимает тяжёлое положение Иссохших лучше, чем синдорай. Моё сердце сочувствует им.$b$bНо Талисре нужно понять, что есть разница между восстанием и войной.$b$bДо сих пор её мятежники справлялись парой стычек здесь и там. Но они не закалены боем так, как мы, эльфы крови.', 24330),
(123564, 'ruRU', '', 'Твоим лидерам нужно включиться в дело.$b$bВереса настолько одержима желанием отомстить Орде, что мы не можем доверить ей наш фланг.$b$bТиранда — часовой. Она мало знает о войне на таком поле боя. Хотя её разведка полезна, ей следует отстранить Калдорай от основного штурма.$b$bМои рыцари крови — единственные, кто готов вынести тяжесть этого конфликта.', 24330),
(123566, 'ruRU', '', 'Мятежники готовы к бою? Впечатляет. Посмотрим, что они умеют.', 24330),
(123567, 'ruRU', '', 'А шал''дорай сильнее, чем ты ожидаешь. Когда придёт время, мы будем сражаться рядом с тобой.', 24330),
(123568, 'ruRU', '', '[CUT]There are still Nightborne in the city who blindly follow the Grand Magistrix. We must be careful not to hurt any innocents!', 24330),
(123569, 'ruRU', '', '[CUT]So be it. I will alert our forces inside the city. There is much I still have to learn about the world we left behind.', 24330);
